32	static int auto_capture(const char* path)
33	{
34	#ifdef CONFIG_SYSTEM_POPEN
35	    /* Validate path: reject shell metacharacters to prevent injection */
36	    for (const char* p = path; *p; p++) {
37	        if (*p == ';' || *p == '|' || *p == '&' || *p == '`'
38	            || *p == '$' || *p == '(' || *p == ')' || *p == '\n') {
39	            syslog(LOG_ERR, "[%s] Rejected path with shell metachar\n", TAG);
40	            return ERROR;
41	        }
42	    }
43	    char cmd[128];
44	    snprintf(cmd, sizeof(cmd), "fbcapture '%s'", path);
45	    syslog(LOG_INFO, "[%s] Auto-capture: %s\n", TAG, cmd);
46	    FILE* pp = popen(cmd, "r");
47	    if (!pp) {
48	        syslog(LOG_ERR, "[%s] popen fbcapture failed\n", TAG);
49	        return ERROR;
50	    }
51	    char buf[128];
52	    while (fgets(buf, sizeof(buf), pp))
53	        ;
54	    int rc = pclose(pp);
55	    syslog(LOG_INFO, "[%s] fbcapture exit=%d\n", TAG, rc);
56	    return (rc == 0) ? OK : ERROR;
57	#else
58	    (void)path;
59	    syslog(LOG_WARNING, "[%s] popen not available, cannot auto-capture\n", TAG);
60	    return ERROR;
61	#endif
62	}
