41	int llm_chat_vision(const char* prompt, const char* image_b64,
42	    const char* mime_type, char* response_buf,
43	    size_t buf_size)
44	{
45	    char model[64], api_key[128], llm_host[128];
46	    llm_snapshot_config(model, sizeof(model),
47	        api_key, sizeof(api_key),
48	        llm_host, sizeof(llm_host));
49	
50	    if (api_key[0] == '\0') {
51	        snprintf(response_buf, buf_size, "Error: No API key configured");
52	        return ERROR;
53	    }
54	
55	    if (!mime_type || !mime_type[0])
56	        mime_type = "image/jpeg";
57	
58	    cJSON* content_arr = cJSON_CreateArray();
59	    cJSON* text_part = cJSON_CreateObject();
60	    cJSON* img_part = cJSON_CreateObject();
61	    cJSON* img_url_obj = cJSON_CreateObject();
62	    cJSON* user_msg = cJSON_CreateObject();
63	    cJSON* messages = cJSON_CreateArray();
64	    cJSON* body = cJSON_CreateObject();
65	    char* data_uri = NULL;
66	
67	    if (!content_arr || !text_part || !img_part || !img_url_obj
68	        || !user_msg || !messages || !body) {
69	        cJSON_Delete(content_arr);
70	        cJSON_Delete(text_part);
71	        cJSON_Delete(img_part);
72	        cJSON_Delete(img_url_obj);
73	        cJSON_Delete(user_msg);
74	        cJSON_Delete(messages);
75	        cJSON_Delete(body);
76	        snprintf(response_buf, buf_size, "Error: OOM building vision JSON");
77	        return ERROR;
78	    }
79	
80	    cJSON_AddStringToObject(text_part, "type", "text");
81	    cJSON_AddStringToObject(text_part, "text",
82	        prompt ? prompt : AGENT_VISION_DEFAULT_PROMPT);
83	    cJSON_AddItemToArray(content_arr, text_part);
84	
85	    size_t b64_len = strlen(image_b64);
86	    size_t prefix_len = 5 + strlen(mime_type) + 8;
87	    size_t uri_len = prefix_len + b64_len + 1;
88	    data_uri = malloc(uri_len);
89	    if (!data_uri) {
90	        cJSON_Delete(content_arr);
91	        cJSON_Delete(img_part);
92	        cJSON_Delete(img_url_obj);
93	        cJSON_Delete(user_msg);
94	        cJSON_Delete(messages);
95	        cJSON_Delete(body);
96	        snprintf(response_buf, buf_size, "Error: OOM building data URI");
97	        return ERROR;
98	    }
99	    snprintf(data_uri, uri_len, "data:%s;base64,%s", mime_type, image_b64);
100	
101	    cJSON_AddStringToObject(img_part, "type", "image_url");
102	    cJSON_AddStringToObject(img_url_obj, "url", data_uri);
103	    cJSON_AddItemToObject(img_part, "image_url", img_url_obj);
104	    cJSON_AddItemToArray(content_arr, img_part);
105	    free(data_uri);
106	
107	    cJSON_AddStringToObject(user_msg, "role", "user");
108	    cJSON_AddItemToObject(user_msg, "content", content_arr);
109	
110	    cJSON_AddItemToArray(messages, user_msg);
111	
112	    cJSON_AddStringToObject(body, "model",
113	        model_name_for_api(model, llm_host));
114	
115	    if (is_openai_compat_host(llm_host))
116	        cJSON_AddNumberToObject(body, "max_completion_tokens",
117	            AGENT_VISION_MAX_TOKENS);
118	    else
119	        cJSON_AddNumberToObject(body, "max_tokens", AGENT_VISION_MAX_TOKENS);
120	
121	    cJSON_AddItemToObject(body, "messages", messages);
122	
123	    char* post_data = cJSON_PrintUnformatted(body);
124	    cJSON_Delete(body);
125	    if (!post_data) {
126	        snprintf(response_buf, buf_size, "Error: Failed to build vision request");
127	        return ERROR;
128	    }
129	
130	    syslog(LOG_INFO, "[%s] Vision API call (model: %s, %d bytes)\n", TAG, model,
131	        (int)strlen(post_data));
132	
133	    resp_buf_t rb = { 0 };
134	    int status = 0;
135	    int err = llm_http_call(post_data, &rb, &status);
136	    free(post_data);
137	
138	    if (err != OK) {
139	        resp_buf_free(&rb);
140	        snprintf(response_buf, buf_size, "Error: Vision HTTP request failed");
141	        return err;
142	    }
143	
144	    if (status != 200) {
145	        syslog(LOG_ERR, "[%s] Vision API error HTTP %d: %.300s\n", TAG, status,
146	            rb.data ? rb.data : "");
147	        snprintf(response_buf, buf_size, "Vision API error (HTTP %d): %.200s",
148	            status, rb.data ? rb.data : "");
149	        resp_buf_free(&rb);
150	        return ERROR;
151	    }
152	
153	    cJSON* root = cJSON_Parse(rb.data);
154	    resp_buf_free(&rb);
155	
156	    if (!root) {
157	        snprintf(response_buf, buf_size, "Error: Failed to parse vision response");
158	        return ERROR;
159	    }
160	
161	    extract_text(root, response_buf, buf_size);
162	    cJSON_Delete(root);
163	
164	    if (response_buf[0] == '\0')
165	        snprintf(response_buf, buf_size, "No response from Vision API");
166	    else
167	        syslog(LOG_INFO, "[%s] Vision response: %d bytes\n", TAG,
168	            (int)strlen(response_buf));
169	
170	    return OK;
171	}
