173	/* ── JSON string escape helper ────────────────────────────── */
174	
175	static char* json_escape_string(const char* src)
176	{
177	    if (!src)
178	        return NULL;
179	
180	    size_t src_len = strlen(src);
181	    size_t cap = src_len * 6 + 1;
182	    char* out = malloc(cap);
183	    if (!out)
184	        return NULL;
185	
186	    char* w = out;
187	    for (const char* r = src; *r; r++) {
188	        unsigned char c = (unsigned char)*r;
189	        switch (c) {
190	        case '"':  *w++ = '\\'; *w++ = '"';  break;
191	        case '\\': *w++ = '\\'; *w++ = '\\'; break;
192	        case '\n': *w++ = '\\'; *w++ = 'n';  break;
193	        case '\r': *w++ = '\\'; *w++ = 'r';  break;
194	        case '\t': *w++ = '\\'; *w++ = 't';  break;
195	        case '\b': *w++ = '\\'; *w++ = 'b';  break;
196	        case '\f': *w++ = '\\'; *w++ = 'f';  break;
197	        default:
198	            if (c < 0x20) {
199	                w += sprintf(w, "\\u%04x", c);
200	            } else {
201	                *w++ = (char)c;
202	            }
203	            break;
204	        }
205	    }
206	    *w = '\0';
207	    return out;
208	}
