211	
212	int llm_chat_vision_raw(const char* prompt,
213	    const unsigned char* raw_image, size_t raw_len,
214	    const char* mime_type,
215	    char* response_buf, size_t buf_size)
216	{
217	    char model[64], api_key[128], llm_host[128];
218	    llm_snapshot_config(model, sizeof(model),
219	        api_key, sizeof(api_key),
220	        llm_host, sizeof(llm_host));
221	
222	    if (api_key[0] == '\0') {
223	        snprintf(response_buf, buf_size, "Error: No API key configured");
224	        return ERROR;
225	    }
226	
227	    if (!mime_type || !mime_type[0])
228	        mime_type = "image/jpeg";
229	
230	    if (!prompt || !prompt[0])
231	        prompt = AGENT_VISION_DEFAULT_PROMPT;
232	
233	    char* escaped_prompt = json_escape_string(prompt);
234	    if (!escaped_prompt) {
235	        snprintf(response_buf, buf_size, "Error: OOM escaping prompt");
236	        return ERROR;
237	    }
238	
239	    int max_tokens = AGENT_VISION_MAX_TOKENS;
240	    const char* tokens_key = is_openai_compat_host(llm_host)
241	        ? "max_completion_tokens"
242	        : "max_tokens";
243	
244	    size_t b64_len = 0;
245	    mbedtls_base64_encode(NULL, 0, &b64_len, raw_image, raw_len);
246	
247	    const char* hdr_fmt = "{\"model\":\"%s\",\"%s\":%d,\"messages\":"
248	                          "[{\"role\":\"user\",\"content\":["
249	                          "{\"type\":\"text\",\"text\":\"%s\"},"
250	                          "{\"type\":\"image_url\",\"image_url\":"
251	                          "{\"url\":\"data:%s;base64,";
252	    const char* trailer = "\"}}]}]}";
253	
254	    size_t hdr_max = strlen(hdr_fmt) + sizeof(model) + 32
255	        + strlen(tokens_key) + strlen(escaped_prompt)
256	        + strlen(mime_type) + 64;
257	    size_t total = hdr_max + b64_len + strlen(trailer) + 1;
258	
259	    char* body = malloc(total);
260	    if (!body) {
261	        free(escaped_prompt);
262	        snprintf(response_buf, buf_size, "Error: OOM building vision request");
263	        return ERROR;
264	    }
265	
266	    int off = snprintf(body, total, hdr_fmt,
267	        model_name_for_api(model, llm_host), tokens_key, max_tokens,
268	        escaped_prompt, mime_type);
269	    free(escaped_prompt);
270	
271	    size_t written = 0;
272	    int rc = mbedtls_base64_encode(
273	        (unsigned char*)(body + off),
274	        total - (size_t)off - strlen(trailer) - 1,
275	        &written, raw_image, raw_len);
276	    if (rc != 0) {
277	        free(body);
278	        snprintf(response_buf, buf_size,
279	            "Error: base64 encode failed (%d)", rc);
280	        return ERROR;
281	    }
282	    off += (int)written;
283	
284	    memcpy(body + off, trailer, strlen(trailer) + 1);
285	
286	    syslog(LOG_INFO,
287	        "[%s] Vision raw API call (model: %s, body=%d bytes, "
288	        "image=%zu raw -> %zu b64)\n",
289	        TAG, model, off + (int)strlen(trailer), raw_len, written);
290	
291	    resp_buf_t rb = { 0 };
292	    int status = 0;
293	    int err = llm_http_call(body, &rb, &status);
294	    free(body);
295	
296	    if (err != OK) {
297	        resp_buf_free(&rb);
298	        snprintf(response_buf, buf_size, "Error: Vision HTTP request failed");
299	        return err;
300	    }
301	
302	    if (status != 200) {
303	        syslog(LOG_ERR, "[%s] Vision raw API error HTTP %d: %.300s\n",
304	            TAG, status, rb.data ? rb.data : "");
305	        snprintf(response_buf, buf_size,
306	            "Vision API error (HTTP %d): %.200s",
307	            status, rb.data ? rb.data : "");
308	        resp_buf_free(&rb);
309	        return ERROR;
310	    }
311	
312	    cJSON* root = cJSON_Parse(rb.data);
313	    resp_buf_free(&rb);
314	
315	    if (!root) {
316	        snprintf(response_buf, buf_size,
317	            "Error: Failed to parse vision response");
318	        return ERROR;
319	    }
320	
321	    extract_text(root, response_buf, buf_size);
322	    cJSON_Delete(root);
323	
324	    if (response_buf[0] == '\0')
325	        snprintf(response_buf, buf_size, "No response from Vision API");
326	    else
327	        syslog(LOG_DEBUG, "[%s] Vision response: %d bytes\n", TAG,
328	            (int)strlen(response_buf));
329	
330	    return OK;
331	}
