77	/**
78	 * Capture one JPEG frame from the camera via V4L2.
79	 *
80	 * @param width    Desired width (320 or 1280)
81	 * @param height   Desired height (180 or 720)
82	 * @param out_data Pointer to receive malloc'd JPEG data (caller frees)
83	 * @param out_size Receives the JPEG data size in bytes
84	 * @return OK on success, ERROR on failure
85	 */
86	static int camera_v4l2_capture(int width, int height,
87	                               uint8_t **out_data, size_t *out_size)
88	{
89	    int fd = -1;
90	    int ret = ERROR;
91	    void *buffers[CAM_NUM_BUFFERS] = { NULL };
92	    size_t buf_sizes[CAM_NUM_BUFFERS] = { 0 };
93	    uint32_t nbuffers = 0;
94	
95	    *out_data = NULL;
96	    *out_size = 0;
97	
98	    /* Open camera device */
99	    fd = open(AGENT_CAMERA_DEV, O_RDWR);
100	    if (fd < 0) {
101	        syslog(LOG_ERR, "[%s] Cannot open %s: %d\n",
102	               TAG, AGENT_CAMERA_DEV, errno);
103	        return ERROR;
104	    }
105	
106	    /* Query capabilities */
107	    struct v4l2_capability cap;
108	    memset(&cap, 0, sizeof(cap));
109	    if (ioctl(fd, VIDIOC_QUERYCAP, (uintptr_t)&cap) < 0) {
110	        syslog(LOG_ERR, "[%s] VIDIOC_QUERYCAP failed: %d\n", TAG, errno);
111	        goto cleanup;
112	    }
113	
114	    if (!(cap.capabilities & V4L2_CAP_VIDEO_CAPTURE)) {
115	        syslog(LOG_ERR, "[%s] Device does not support video capture\n", TAG);
116	        goto cleanup;
117	    }
118	
119	    /* Set format: hardware JPEG encoder */
120	    struct v4l2_format fmt;
121	    memset(&fmt, 0, sizeof(fmt));
122	    fmt.type                = V4L2_BUF_TYPE_VIDEO_CAPTURE;
123	    fmt.fmt.pix.width       = width;
124	    fmt.fmt.pix.height      = height;
125	    fmt.fmt.pix.pixelformat = V4L2_PIX_FMT_JPEG;
126	    fmt.fmt.pix.sizeimage   = CAM_BUF_SIZE;
127	    fmt.fmt.pix.field       = V4L2_FIELD_NONE;
128	
129	    if (ioctl(fd, VIDIOC_S_FMT, (uintptr_t)&fmt) < 0) {
130	        /* Fallback: try V4L2_PIX_FMT_ENTROPY (BES hardware JPEG) */
131	        fmt.fmt.pix.pixelformat = V4L2_PIX_FMT_ENTROPY;
132	        if (ioctl(fd, VIDIOC_S_FMT, (uintptr_t)&fmt) < 0) {
133	            syslog(LOG_ERR, "[%s] VIDIOC_S_FMT failed: %d\n", TAG, errno);
134	            goto cleanup;
135	        }
136	    }
137	
138	    syslog(LOG_INFO, "[%s] Format set: %dx%d\n", TAG, width, height);
139	
140	    /* Request buffers */
141	    struct v4l2_requestbuffers req;
142	    memset(&req, 0, sizeof(req));
143	    req.count  = CAM_NUM_BUFFERS;
144	    req.type   = V4L2_BUF_TYPE_VIDEO_CAPTURE;
145	    req.memory = V4L2_MEMORY_MMAP;
146	
147	    if (ioctl(fd, VIDIOC_REQBUFS, (uintptr_t)&req) < 0) {
148	        syslog(LOG_ERR, "[%s] VIDIOC_REQBUFS failed: %d\n", TAG, errno);
149	        goto cleanup;
150	    }
151	
152	    nbuffers = req.count;
153	
154	    /* Query and mmap buffers */
155	    for (uint32_t i = 0; i < nbuffers; i++) {
156	        struct v4l2_buffer buf;
157	        memset(&buf, 0, sizeof(buf));
158	        buf.type   = V4L2_BUF_TYPE_VIDEO_CAPTURE;
159	        buf.memory = V4L2_MEMORY_MMAP;
160	        buf.index  = i;
161	
162	        if (ioctl(fd, VIDIOC_QUERYBUF, (uintptr_t)&buf) < 0) {
163	            syslog(LOG_ERR, "[%s] VIDIOC_QUERYBUF %u failed\n", TAG, i);
164	            goto cleanup;
165	        }
166	
167	        buf_sizes[i] = buf.length;
168	        buffers[i] = mmap(NULL, buf.length, PROT_READ | PROT_WRITE,
169	                          MAP_SHARED, fd, buf.m.offset);
170	        if (buffers[i] == MAP_FAILED) {
171	            buffers[i] = NULL;
172	            syslog(LOG_ERR, "[%s] mmap buffer %u failed\n", TAG, i);
173	            goto cleanup;
174	        }
175	    }
176	
177	    /* Enqueue all buffers */
178	    for (uint32_t i = 0; i < nbuffers; i++) {
179	        struct v4l2_buffer buf;
180	        memset(&buf, 0, sizeof(buf));
181	        buf.type   = V4L2_BUF_TYPE_VIDEO_CAPTURE;
182	        buf.memory = V4L2_MEMORY_MMAP;
183	        buf.index  = i;
184	
185	        if (ioctl(fd, VIDIOC_QBUF, (uintptr_t)&buf) < 0) {
186	            syslog(LOG_ERR, "[%s] VIDIOC_QBUF %u failed\n", TAG, i);
187	            goto cleanup;
188	        }
189	    }
190	
191	    /* Start streaming */
192	    enum v4l2_buf_type type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
193	    if (ioctl(fd, VIDIOC_STREAMON, (uintptr_t)&type) < 0) {
194	        syslog(LOG_ERR, "[%s] VIDIOC_STREAMON failed: %d\n", TAG, errno);
195	        goto cleanup;
196	    }
197	
198	    /* Dequeue one frame with timeout to avoid blocking the agent loop */
199	    struct pollfd pfd = { .fd = fd, .events = POLLIN };
200	    int poll_ret = poll(&pfd, 1, CAM_DQBUF_TIMEOUT_MS);
201	    if (poll_ret <= 0) {
202	        syslog(LOG_ERR, "[%s] Frame capture timeout (%d ms)\n",
203	               TAG, CAM_DQBUF_TIMEOUT_MS);
204	        ioctl(fd, VIDIOC_STREAMOFF, (uintptr_t)&type);
205	        goto cleanup;
206	    }
207	
208	    struct v4l2_buffer dqbuf;
209	    memset(&dqbuf, 0, sizeof(dqbuf));
210	    dqbuf.type   = V4L2_BUF_TYPE_VIDEO_CAPTURE;
211	    dqbuf.memory = V4L2_MEMORY_MMAP;
212	
213	    if (ioctl(fd, VIDIOC_DQBUF, (uintptr_t)&dqbuf) < 0) {
214	        syslog(LOG_ERR, "[%s] VIDIOC_DQBUF failed: %d\n", TAG, errno);
215	        ioctl(fd, VIDIOC_STREAMOFF, (uintptr_t)&type);
216	        goto cleanup;
217	    }
218	
219	    syslog(LOG_INFO, "[%s] Captured frame: %u bytes from buffer %u\n",
220	           TAG, dqbuf.bytesused, dqbuf.index);
221	
222	    /* Copy JPEG data out (mmap buffer will be released) */
223	    if (dqbuf.bytesused > 0 && dqbuf.index < nbuffers) {
224	        *out_data = malloc(dqbuf.bytesused);
225	        if (*out_data) {
226	            memcpy(*out_data, buffers[dqbuf.index], dqbuf.bytesused);
227	            *out_size = dqbuf.bytesused;
228	            ret = OK;
229	        } else {
230	            syslog(LOG_ERR, "[%s] OOM copying frame (%u bytes)\n",
231	                   TAG, dqbuf.bytesused);
232	        }
233	    }
234	
235	    /* Stop streaming */
236	    ioctl(fd, VIDIOC_STREAMOFF, (uintptr_t)&type);
237	
238	cleanup:
239	    /* Unmap buffers */
240	    for (uint32_t i = 0; i < nbuffers; i++) {
241	        if (buffers[i] && buffers[i] != MAP_FAILED) {
242	            munmap(buffers[i], buf_sizes[i]);
243	        }
244	    }
245	
246	    /* Release buffers */
247	    if (fd >= 0) {
248	        struct v4l2_requestbuffers rel;
249	        memset(&rel, 0, sizeof(rel));
250	        rel.count  = 0;
251	        rel.type   = V4L2_BUF_TYPE_VIDEO_CAPTURE;
252	        rel.memory = V4L2_MEMORY_MMAP;
253	        ioctl(fd, VIDIOC_REQBUFS, (uintptr_t)&rel);
254	        close(fd);
255	    }
256	
257	    return ret;
258	}
