/* 内部共享函数 */
static int _recognize_with_provider(const char *provider_name,
    const char *prompt, char *output, size_t output_size)
{
    image_data_t img = {0};
    int ret = image_provider_capture(provider_name, &img);
    if (ret != OK) {
        snprintf(output, output_size,
            "{\"error\":\"Failed to capture image from provider '%s'\"}", provider_name);
        return ERROR;
    }

    char *resp = calloc(1, output_size);
    ret = llm_chat_vision_raw(prompt ? prompt : AGENT_VISION_DEFAULT_PROMPT,
        img.data, img.size, img.mime_type, resp, output_size);
    image_data_free(&img);

    if (ret != OK) {
        snprintf(output, output_size, "{\"error\":\"%s\"}", resp);
        free(resp);
        return ERROR;
    }

    cJSON *result = cJSON_CreateObject();
    cJSON_AddStringToObject(result, "analysis", resp);
    free(resp);
    char *json = cJSON_PrintUnformatted(result);
    cJSON_Delete(result);
    if (json) {
        strncpy(output, json, output_size - 1);
        output[output_size - 1] = '\0';
        free(json);
    }
    return OK;
}

/* 工具 1: 摄像头拍照识别 */
